/// <summary>
/// The <c>METTelemetryProperties</c> class contains all available event properties that can be used in the Application Insights telemetry.
/// </summary>
/// <remarks>
/// The names must be unique.
/// Please keep the list sorted alphabetically in ascending order.
/// </remarks>
public static final class METTelemetryProperties
{
    public const str orderReferenceNumber   = 'orderReferenceNumber';
    public const str warehouseId            = 'warehouseId';
    public const str industryKey            = 'industryKey';
    public const str metcashSalesOrderType  = 'metcashSalesOrderType';
    public const str salesOrderNumber       = 'salesOrderNumber';
    public const str customerNumber         = 'customerNumber';
    public const str transmissionNumber     = 'transmissionNumber';
    public const str confirmDocNum          = 'confirmDocNum';
}
